def captainAmerica(N, M, V):
    from collections import defaultdict, deque

    # Build the graph
    graph = defaultdict(list)
    in_degree = [0] * (N + 1)

    for u, v in V:
        graph[u].append(v)
        in_degree[v] += 1

    # Initialize the queue with nodes having zero in-degree
    queue = deque()
    for i in range(1, N + 1):
        if in_degree[i] == 0:
            queue.append(i)

    # Process the queue
    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # Count the number of nodes with zero in-degree
    count = sum(1 for degree in in_degree[1:] if degree == 0)

    return count
